        if !app.wait(for: .runningForeground, timeout: 15) {
            app.launch()
            _ = app.wait(for: .runningForeground, timeout: 20)
        }
        app.activate()

        let searchTab = app.tabBars.buttons["Search"]
        if searchTab.waitForExistence(timeout: 30) {
            searchTab.tap()
        } else {
            let tabs = app.tabBars.firstMatch.buttons
            if tabs.count > 1 {
                tabs.element(boundBy: 1).tap()
            }
        }

        var field = app.textFields.firstMatch
        if !field.waitForExistence(timeout: 15) {
            field = app.searchFields.firstMatch
        }
        if field.waitForExistence(timeout: 10) {
            field.tap()
            field.typeText("cat")
        } else {
            print("HIERARCHY: " + app.debugDescription)
        }

        if app.keyboards.firstMatch.waitForExistence(timeout: 5) {
            let searchKey = app.keyboards.buttons["search"]
            if searchKey.exists {
                searchKey.tap()
            } else if app.keyboards.buttons["Search"].exists {
                app.keyboards.buttons["Search"].tap()
            } else if app.keyboards.buttons["return"].exists {
                app.keyboards.buttons["return"].tap()
            }
        }

        sleep(6)
    }
}

